import {scenarioSpeedReport,resumeScenarioSpeed} from './scenario-speed.js?v=scenario-stages-1';
import {scenarioStory} from './scenario-story.js?v=scenario-stages-1';
import {scenarioEventReport} from './scenario-events.js?v=scenario-stages-1';
import {showCustomScenarioEditor} from './scenario-editor.js?v=scenario-stages-1';
import {SCENARIOS,scenarioGoals,scenarioDefinition} from './scenarios.js?v=scenario-stages-1';
export function showScenarios(ui){const {city,dialog,close,start,exportCity,review,update,save}=ui,c=city(),s=c.scenario,$=v=>document.querySelector(v);
 if(s){const goals=scenarioGoals(c),d=scenarioDefinition(s),remaining=Math.max(0,d.months-(c.month-s.startMonth));dialog('Scenario status · '+d.title,`<p>${s.status==='playing'?`${remaining} months remain. Goals are checked at the end of each simulation month.`:s.status==='won'?`Scenario won · ${s.rank}. Completed in ${s.endedMonth-s.startMonth} months.`:`Scenario lost: the ${d.months}-month deadline passed before all goals were met.`}</p><p>${d.description}</p>${scenarioSpeedReport(c)}<ol>${goals.map((g,i)=>`<li><strong>${g.done?'✓ ':''}${g.title}</strong><br>${g.detail}${g.area&&ui.viewArea?`<br><button data-goal-area="${i}">View goal area</button>`:''}</li>`).join('')}</ol>${s.id==='custom'?scenarioStory(s,c):`<p>${d.briefing}</p>`}${scenarioEventReport(c)}<div class="actions">${s.id==='custom'&&s.status==='playing'&&ui.resume?`<button id="resumeScenario">Play at ${resumeScenarioSpeed(c)}×</button>`:''}<button id="backScenario" class="primary">${s.status==='playing'?'Return to city':'Continue as sandbox'}</button>${s.id==='custom'?'':'<button id="retryScenario">Restart this challenge</button>'}${s.id==='custom'?'<button id="exportCustomScenario">Export challenge city</button>':''}<button id="otherScenarios">Choose another challenge</button><button id="reviewScenario">Milestone 6 feedback</button></div><p class="fine">${s.id==='custom'?'Player-authored challenge. Reimport an exported starting city to replay it.':'Original SIMS3000 challenge. Goals and timing are authored for this reconstruction, not a reproduction of a shipped SimCity scenario.'}</p>`);document.querySelectorAll('[data-event-camera]').forEach(button=>button.onclick=()=>ui.viewCamera?.(s.definition.events[Number(button.dataset.eventCamera)]));document.querySelectorAll('[data-goal-area]').forEach(button=>button.onclick=()=>ui.viewArea(goals[Number(button.dataset.goalArea)].area));if($('#resumeScenario'))$('#resumeScenario').onclick=()=>{close();ui.resume();};$('#backScenario').onclick=()=>{if(s.status!=='playing'){c.scenario=null;save();update();}close();};if(s.id==='custom')$('#exportCustomScenario').onclick=exportCity;if(s.id!=='custom')$('#retryScenario').onclick=()=>confirm(s.id);$('#otherScenarios').onclick=chooser;$('#reviewScenario').onclick=()=>review(6);
 }else chooser();
 function chooser(){dialog('Play a scenario',`<button id="createCustomScenario" class="primary">Create a challenge from this city</button><p>Choose a prepared city with goals and a deadline. These are original challenges using the manual’s scenario format.</p>${Object.entries(SCENARIOS).map(([id,d])=>`<div class="milestone"><small>${d.months/12} YEARS · ORIGINAL CHALLENGE</small><h3>${d.title}</h3><p>${d.description}</p><button data-scenario="${id}">View briefing</button></div>`).join('')}`);$('#createCustomScenario').onclick=()=>showCustomScenarioEditor(ui,()=>showScenarios(ui));document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>confirm(b.dataset.scenario));}
 function confirm(id){const d=SCENARIOS[id];dialog(d.title,`<p>${d.description}</p><p>${d.briefing}</p><p>Starting replaces your current city and autosave. Export the current city to keep a copy.</p><div class="actions"><button id="exportScenario">Export current city</button><button id="startScenario" class="primary">Start challenge</button><button id="cancelScenario">Back to scenarios</button></div>`);$('#exportScenario').onclick=exportCity;$('#startScenario').onclick=()=>{start(id);close();};$('#cancelScenario').onclick=chooser;}
}
